1	package shadow
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"time"
7	)
8	
9	// diskVersion 是升级版本登记的磁盘格式。
10	type diskVersion struct {
11		Target      string   `json:"target"`
12		AllowedFrom []string `json:"allowedFrom"`
13	}
14	
15	// diskCampaign 是活动的磁盘格式，设备按提交次序保存。
16	type diskCampaign struct {
17		ID                string       `json:"id"`
18		Operator          string       `json:"operator"`
19		Target            string       `json:"target"`
20		CreatedAt         time.Time    `json:"createdAt"`
21		BatchSize         int          `json:"batchSize"`
22		WindowStart       time.Time    `json:"windowStart"`
23		WindowEnd         time.Time    `json:"windowEnd"`
24		Deadline          time.Time    `json:"deadline"`
25		RollbackOnFailure bool         `json:"rollbackOnFailure,omitempty"`
26		LastTime          time.Time    `json:"lastTime"`
27		Status            string       `json:"status"`
28		Ended             bool         `json:"ended"`
29		EndedAt           time.Time    `json:"endedAt,omitempty"`
30		Devices           []diskDev    `json:"devices"`
31		Results           []diskResult `json:"results,omitempty"`
32	}
33	
34	type diskOp struct {
35		ID            string          `json:"id"`
36		Claimed       bool            `json:"claimed"`
37		ClaimedAt     time.Time       `json:"claimedAt,omitempty"`
38		HasResult     bool            `json:"hasResult"`
39		Success       bool            `json:"success"`
40		Reason        string          `json:"reason,omitempty"`
41		At            time.Time       `json:"at,omitempty"`
42		ResultSeq     uint64          `json:"resultSeq,omitempty"`
43		ResultVersion string          `json:"resultVersion,omitempty"`
44		ResultConfig  json.RawMessage `json:"resultConfig,omitempty"`
45	}
46	
47	type diskDev struct {
48		DeviceID       string    `json:"deviceId"`
49		Batch          int       `json:"batch"`
50		Status         string    `json:"status"`
51		Phase          string    `json:"phase"`
52		Reason         string    `json:"reason,omitempty"`
53		At             time.Time `json:"at,omitempty"`
54		Download       diskOp    `json:"download"`
55		Install        diskOp    `json:"install"`
56		Rollback       diskOp    `json:"rollback,omitempty"`
57		RollbackTarget string    `json:"rollbackTarget,omitempty"`
58	}
59	
60	type diskResult struct {
61		DeviceID    string    `json:"deviceId"`
62		OperationID string    `json:"operationId"`
63		Stage       string    `json:"stage"`
64		Success     bool      `json:"success"`
65		Reason      string    `json:"reason,omitempty"`
66		Version     string    `json:"version,omitempty"`
67		At          time.Time `json:"at"`
68	}
69	
70	func (s *Store) marshalVersions() map[string]diskVersion {
71		out := make(map[string]diskVersion, len(s.versions))
72		for k, v := range s.versions {
73			out[k] = diskVersion{Target: v.Target, AllowedFrom: append([]string(nil), v.AllowedFrom...)}
74		}
75		return out
76	}
77	
78	func (s *Store) marshalCampaigns() (map[string]diskCampaign, error) {
79		out := make(map[string]diskCampaign, len(s.campaigns))
80		for id, c := range s.campaigns {
81			dc := diskCampaign{
82				ID:                c.ID,
83				Operator:          c.Operator,
84				Target:            c.Target,
85				CreatedAt:         c.CreatedAt,
86				BatchSize:         c.BatchSize,
87				WindowStart:       c.WindowStart,
88				WindowEnd:         c.WindowEnd,
89				Deadline:          c.Deadline,
90				RollbackOnFailure: c.RollbackOnFailure,
91				LastTime:          c.LastTime,
92				Status:            c.Status,
93				Ended:             c.Ended,
94				EndedAt:           c.EndedAt,
95				Results:           make([]diskResult, 0, len(c.Results)),
96			}
97			for _, cd := range c.Devices {
98				dc.Devices = append(dc.Devices, diskDev{
99					DeviceID:       cd.DeviceID,
100					Batch:          cd.Batch,
101					Status:         cd.Status,
102					Phase:          cd.Phase,
103					Reason:         cd.Reason,
104					At:             cd.At,
105					Download:       encodeOp(cd.Download),
106					Install:        encodeOp(cd.Install),
107					Rollback:       encodeOp(cd.Rollback),
108					RollbackTarget: cd.RollbackTarget,
109				})
110			}
111			for _, r := range c.Results {
112				dc.Results = append(dc.Results, diskResult{
113					DeviceID:    r.DeviceID,
114					OperationID: r.OperationID,
115					Stage:       r.Stage,
116					Success:     r.Success,
117					Reason:      r.Reason,
118					Version:     r.Version,
119					At:          r.At,
120				})
121			}
122			out[id] = dc
123		}
124		return out, nil
125	}
126	
127	func encodeOp(o opState) diskOp {
128		return diskOp{
129			ID:            o.ID,
130			Claimed:       o.Claimed,
131			ClaimedAt:     o.ClaimedAt,
132			HasResult:     o.HasResult,
133			Success:       o.Success,
134			Reason:        o.Reason,
135			At:            o.At,
136			ResultSeq:     o.ResultSeq,
137			ResultVersion: o.ResultVersion,
138			ResultConfig:  cloneRaw(o.ResultConfig),
139		}
140	}
141	
142	func decodeOp(d diskOp) opState {
143		return opState{
144			ID:            d.ID,
145			Claimed:       d.Claimed,
146			ClaimedAt:     d.ClaimedAt,
147			HasResult:     d.HasResult,
148			Success:       d.Success,
149			Reason:        d.Reason,
150			At:            d.At,
151			ResultSeq:     d.ResultSeq,
152			ResultVersion: d.ResultVersion,
153			ResultConfig:  cloneRaw(d.ResultConfig),
154		}
155	}
156	
157	// restoreVersions 恢复并校验版本登记。
158	func (s *Store) restoreVersions(disk map[string]diskVersion) error {
159		out := make(map[string]*versionState, len(disk))
160		for k, dv := range disk {
161			if k == "" || dv.Target == "" || k != dv.Target {
162				return fmt.Errorf("%w: invalid upgrade version entry", ErrCorruptStorage)
163			}
164			if err := validateAllowedFrom(dv.Target, dv.AllowedFrom); err != nil {
165				return fmt.Errorf("%w: version %s: %v", ErrCorruptStorage, dv.Target, err)
166			}
167			out[k] = &versionState{Target: dv.Target, AllowedFrom: append([]string(nil), dv.AllowedFrom...)}
168		}
169		s.versions = out
170		return nil
171	}
172	
173	// expectedHist 是从已保存操作结果推导出的应有历史条目。
174	type expectedHist struct {
175		deviceID string
176		stage    string
177		op       diskOp
178	}
179	
180	// restoreCampaigns 恢复活动并做一致性校验。版本、设备引用、操作标识、
181	// 结果历史都必须自洽，否则整个存储拒绝打开。
182	func (s *Store) restoreCampaigns(disk map[string]diskCampaign) error {
183		out := make(map[string]*campaignState, len(disk))
184		for id, dc := range disk {
185			if id == "" || dc.ID != id {
186				return fmt.Errorf("%w: campaign id mismatch", ErrCorruptStorage)
187			}
188			if dc.Operator == "" || dc.Target == "" || dc.BatchSize <= 0 {
189				return fmt.Errorf("%w: campaign %s invalid", ErrCorruptStorage, id)
190			}
191			if dc.CreatedAt.IsZero() || dc.WindowStart.IsZero() || dc.WindowEnd.IsZero() || dc.Deadline.IsZero() {
192				return fmt.Errorf("%w: campaign %s missing time", ErrCorruptStorage, id)
193			}
194			if !dc.WindowStart.Before(dc.WindowEnd) || !dc.Deadline.After(dc.CreatedAt) {
195				return fmt.Errorf("%w: campaign %s invalid time range", ErrCorruptStorage, id)
196			}
197			if _, ok := s.versions[dc.Target]; !ok {
198				return fmt.Errorf("%w: campaign %s target %s missing", ErrCorruptStorage, id, dc.Target)
199			}
200			if dc.Status != CampaignRunning && dc.Status != CampaignSucceeded && dc.Status != CampaignFailed {
201				return fmt.Errorf("%w: campaign %s bad status", ErrCorruptStorage, id)
202			}
203			if dc.Ended == (dc.Status == CampaignRunning) {
204				return fmt.Errorf("%w: campaign %s ended/status mismatch", ErrCorruptStorage, id)
205			}
206			if len(dc.Devices) == 0 {
207				return fmt.Errorf("%w: campaign %s has no devices", ErrCorruptStorage, id)
208			}
209			c := &campaignState{
210				ID:                dc.ID,
211				Operator:          dc.Operator,
212				Target:            dc.Target,
213				CreatedAt:         dc.CreatedAt,
214				BatchSize:         dc.BatchSize,
215				WindowStart:       dc.WindowStart,
216				WindowEnd:         dc.WindowEnd,
217				Deadline:          dc.Deadline,
218				RollbackOnFailure: dc.RollbackOnFailure,
219				LastTime:          dc.LastTime,
220				Status:            dc.Status,
221				Ended:             dc.Ended,
222				EndedAt:           dc.EndedAt,
223				index:             map[string]int{},
224			}
225			if c.LastTime.IsZero() {
226				c.LastTime = c.CreatedAt
227			}
228			if c.LastTime.Before(c.CreatedAt) {
229				return fmt.Errorf("%w: campaign %s last time before creation", ErrCorruptStorage, id)
230			}
231			seen := map[string]bool{}
232			// expected 按操作标识收集每个已有结果（HasResult）的下载/安装/回滚
233			// 操作所对应的唯一应有历史条目，随后与保存的结果历史逐条对账。
234			expected := map[string]expectedHist{}
235			for i, dd := range dc.Devices {
236				if dd.DeviceID == "" || seen[dd.DeviceID] {
237					return fmt.Errorf("%w: campaign %s device list invalid", ErrCorruptStorage, id)
238				}
239				seen[dd.DeviceID] = true
240				if _, ok := s.devices[dd.DeviceID]; !ok {
241					return fmt.Errorf("%w: campaign %s device %s missing", ErrCorruptStorage, id, dd.DeviceID)
242				}
243				if dd.Batch != i/dc.BatchSize {
244					return fmt.Errorf("%w: campaign %s batch mismatch", ErrCorruptStorage, id)
245				}
246				if !validDeviceStatus(dd.Status) {
247					return fmt.Errorf("%w: campaign %s bad device status", ErrCorruptStorage, id)
248				}
249				if dd.Phase != StageDownload && dd.Phase != StageInstall && dd.Phase != StageRollback {
250					return fmt.Errorf("%w: campaign %s bad phase", ErrCorruptStorage, id)
251				}
252				wantDL := operationID(id, dd.DeviceID, StageDownload)
253				wantIN := operationID(id, dd.DeviceID, StageInstall)
254				wantRB := operationID(id, dd.DeviceID, StageRollback)
255				if dd.Download.ID != wantDL || dd.Install.ID != wantIN {
256					return fmt.Errorf("%w: campaign %s operation id mismatch", ErrCorruptStorage, id)
257				}
258				if dc.RollbackOnFailure {
259					if dd.Rollback.ID != wantRB {
260						return fmt.Errorf("%w: campaign %s rollback op id mismatch", ErrCorruptStorage, id)
261					}
262				} else {
263					// 未开启回滚的活动（含旧存储）不得残留任何回滚进展；
264					// 回滚标识允许缺省（旧存储）或等于稳定标识（新存储）。
265					if dd.Rollback.ID != "" && dd.Rollback.ID != wantRB {
266						return fmt.Errorf("%w: campaign %s rollback op id mismatch", ErrCorruptStorage, id)
267					}
268					if dd.RollbackTarget != "" ||
269						dd.Rollback.Claimed || dd.Rollback.HasResult ||
270						dd.Status == DeviceAwaitingRollback || dd.Status == DeviceRollingBack ||
271						dd.Phase == StageRollback || isRollbackTerminal(dd.Status) {
272						return fmt.Errorf("%w: campaign %s rollback state in non-rollback campaign", ErrCorruptStorage, id)
273					}
274				}
275				// 终态设备必须带时间；失败还须带阶段与原因。
276				if isTerminal(dd.Status) && dd.At.IsZero() {
277					return fmt.Errorf("%w: campaign %s terminal without time", ErrCorruptStorage, id)
278				}
279				if dd.Status == DeviceFailed && dd.Reason == "" {
280					return fmt.Errorf("%w: campaign %s failure without reason", ErrCorruptStorage, id)
281				}
282				if (dd.Status == DeviceRollbackFailed || dd.Status == DeviceRollbackTimeout ||
283					dd.Status == DeviceAwaitingRollback) && dd.Reason == "" {
284					return fmt.Errorf("%w: campaign %s rollback without reason", ErrCorruptStorage, id)
285				}
286				if dd.Status == DeviceSucceeded &&
287					!(dd.Download.HasResult && dd.Download.Success && dd.Install.HasResult && dd.Install.Success) {
288					return fmt.Errorf("%w: campaign %s succeeded device without results", ErrCorruptStorage, id)
289				}
290				if dd.Status == DeviceFailed {
291					failedOp := dd.Download
292					if dd.Phase == StageInstall {
293						failedOp = dd.Install
294					}
295					if !failedOp.HasResult || failedOp.Success {
296						return fmt.Errorf("%w: campaign %s failed device without failed result", ErrCorruptStorage, id)
297					}
298				}
299				if dd.Status == DeviceReady && !(dd.Download.HasResult && dd.Download.Success) {
300					return fmt.Errorf("%w: campaign %s ready device without download", ErrCorruptStorage, id)
301				}
302				ops := []diskOp{dd.Download, dd.Install}
303				if dc.RollbackOnFailure {
304					ops = append(ops, dd.Rollback)
305				}
306				for _, o := range ops {
307					if o.HasResult {
308						if !o.Claimed {
309							return fmt.Errorf("%w: campaign %s unclaimed result", ErrCorruptStorage, id)
310						}
311						if o.At.IsZero() {
312							return fmt.Errorf("%w: campaign %s result without time", ErrCorruptStorage, id)
313						}
314						if !o.Success && o.Reason == "" {
315							return fmt.Errorf("%w: campaign %s failed result without reason", ErrCorruptStorage, id)
316						}
317					}
318					if o.Claimed && o.ClaimedAt.IsZero() {
319						return fmt.Errorf("%w: campaign %s claim without time", ErrCorruptStorage, id)
320					}
321				}
322				if dd.Install.HasResult && !(dd.Download.HasResult && dd.Download.Success) {
323					return fmt.Errorf("%w: campaign %s install before download", ErrCorruptStorage, id)
324				}
325				if dd.Install.Claimed && !(dd.Download.HasResult && dd.Download.Success) {
326					return fmt.Errorf("%w: campaign %s install claimed before download", ErrCorruptStorage, id)
327				}
328				if dd.Install.HasResult && dd.Install.Success {
329					if dd.Install.ResultVersion != dc.Target {
330						return fmt.Errorf("%w: campaign %s install version mismatch", ErrCorruptStorage, id)
331					}
332					if _, ok := decodeObject(dd.Install.ResultConfig); !ok {
333						return fmt.Errorf("%w: campaign %s install config invalid", ErrCorruptStorage, id)
334					}
335				}
336				if dc.RollbackOnFailure {
337					if err := validateRollbackDisk(id, dd); err != nil {
338						return err
339					}
340				}
341				rbOp := decodeOp(dd.Rollback)
342				if !dc.RollbackOnFailure {
343					// 与创建路径一致：内存中始终持有稳定的回滚操作标识。
344					rbOp = opState{ID: wantRB}
345				}
346				cd := &campaignDevice{
347					DeviceID:       dd.DeviceID,
348					Batch:          dd.Batch,
349					Status:         dd.Status,
350					Phase:          dd.Phase,
351					Reason:         dd.Reason,
352					At:             dd.At,
353					Download:       decodeOp(dd.Download),
354					Install:        decodeOp(dd.Install),
355					Rollback:       rbOp,
356					RollbackTarget: dd.RollbackTarget,
357				}
358				c.index[cd.DeviceID] = len(c.Devices)
359				c.Devices = append(c.Devices, cd)
360				// 每个已有结果的操作都应当恰好对应一条结果历史；
361				// 已领取未完成、超时或因前批失败而未执行的阶段没有结果，不入账。
362				addExpected := func(o diskOp, stage string) {
363					if !o.HasResult {
364						return
365					}
366					expected[o.ID] = expectedHist{deviceID: dd.DeviceID, stage: stage, op: o}
367				}
368				addExpected(dd.Download, StageDownload)
369				addExpected(dd.Install, StageInstall)
370				if dc.RollbackOnFailure {
371					addExpected(dd.Rollback, StageRollback)
372				}
373			}
374			// seenHistory 记录已经与保存历史对过账的操作标识。
375			seenHistory := map[string]bool{}
376			var prevAt time.Time
377			for i, dr := range dc.Results {
378				if dr.At.IsZero() {
379					return fmt.Errorf("%w: campaign %s result without time", ErrCorruptStorage, id)
380				}
381				// 历史按接受顺序保存：时间不得倒退；同一时刻按保存次序排列。
382				if i > 0 && dr.At.Before(prevAt) {
383					return fmt.Errorf("%w: campaign %s result history out of order", ErrCorruptStorage, id)
384				}
385				prevAt = dr.At
386				if _, ok := c.index[dr.DeviceID]; !ok {
387					return fmt.Errorf("%w: campaign %s result device mismatch", ErrCorruptStorage, id)
388				}
389				if dr.Stage != StageDownload && dr.Stage != StageInstall && dr.Stage != StageRollback {
390					return fmt.Errorf("%w: campaign %s result stage invalid", ErrCorruptStorage, id)
391				}
392				if dr.Stage == StageRollback && !dc.RollbackOnFailure {
393					return fmt.Errorf("%w: campaign %s rollback result in non-rollback campaign", ErrCorruptStorage, id)
394				}
395				wantOp := operationID(id, dr.DeviceID, dr.Stage)
396				if dr.OperationID != wantOp {
397					return fmt.Errorf("%w: campaign %s result op id mismatch", ErrCorruptStorage, id)
398				}
399				if seenHistory[dr.OperationID] {
400					return fmt.Errorf("%w: campaign %s duplicated result history", ErrCorruptStorage, id)
401				}
402				seenHistory[dr.OperationID] = true
403				// 历史必须对应该设备该阶段实际已有的结果：多出记录、设备或阶段不符
404				// 都按损坏处理，不能通过删历史或补结果把矛盾隐藏起来。
405				want, ok := expected[dr.OperationID]
406				if !ok {
407					return fmt.Errorf("%w: campaign %s result history without operation result", ErrCorruptStorage, id)
408				}
409				if want.deviceID != dr.DeviceID || want.stage != dr.Stage {
410					return fmt.Errorf("%w: campaign %s result history stage mismatch", ErrCorruptStorage, id)
411				}
412				if !dr.Success && dr.Reason == "" {
413					return fmt.Errorf("%w: campaign %s failed result without reason", ErrCorruptStorage, id)
414				}
415				o := want.op
416				if o.Success != dr.Success {
417					return fmt.Errorf("%w: campaign %s result history success mismatch", ErrCorruptStorage, id)
418				}
419				// 失败原因必须一致。成功结果的原因不进入历史（提交路径亦不拒绝
420				// 成功结果附带原因），故只对失败结果比对原因。
421				if !o.Success && o.Reason != dr.Reason {
422					return fmt.Errorf("%w: campaign %s result history reason mismatch", ErrCorruptStorage, id)
423				}
424				// 时间按同一时刻判断，不因时区表示不同而冲突。
425				if !o.At.Equal(dr.At) {
426					return fmt.Errorf("%w: campaign %s result history time mismatch", ErrCorruptStorage, id)
427				}
428				// 安装或回滚成功时记录的版本必须与当次操作接受的版本一致。
429				if dr.Success && (dr.Stage == StageInstall || dr.Stage == StageRollback) {
430					if dr.Version != o.ResultVersion || dr.Version == "" {
431						return fmt.Errorf("%w: campaign %s result history version mismatch", ErrCorruptStorage, id)
432					}
433				} else if dr.Version != "" {
434					// 下载成功及任何失败结果都不携带版本。
435					return fmt.Errorf("%w: campaign %s result history with unexpected version", ErrCorruptStorage, id)
436				}
437				c.Results = append(c.Results, ResultRecord{
438					DeviceID:    dr.DeviceID,
439					OperationID: dr.OperationID,
440					Stage:       dr.Stage,
441					Success:     dr.Success,
442					Reason:      dr.Reason,
443					Version:     dr.Version,
444					At:          dr.At,
445				})
446			}
447			// 反向对账：每个已有结果的操作都必须恰好有一条历史；缺少记录即损坏。
448			for opID, want := range expected {
449				if !seenHistory[opID] {
450					return fmt.Errorf("%w: campaign %s device %s %s result missing history",
451						ErrCorruptStorage, id, want.deviceID, want.stage)
452				}
453			}
454			out[id] = c
455		}
456		// 设备不能同时参加多个未结束活动。
457		busy := map[string]string{}
458		for id, c := range out {
459			if c.Ended {
460				continue
461			}
462			for _, cd := range c.Devices {
463				if other, ok := busy[cd.DeviceID]; ok {
464					return fmt.Errorf("%w: device %s in active campaigns %s and %s",
465						ErrCorruptStorage, cd.DeviceID, other, id)
466				}
467				busy[cd.DeviceID] = id
468			}
469		}
470		s.campaigns = out
471		return nil
472	}
473	
474	func validDeviceStatus(status string) bool {
475		switch status {
476		case DevicePending, DeviceDownloading, DeviceReady, DeviceInstalling,
477			DeviceSucceeded, DeviceFailed, DeviceTimeout, DeviceSkipped,
478			DeviceAwaitingRollback, DeviceRollingBack,
479			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
480			return true
481		default:
482			return false
483		}
484	}
485	
486	// isRollbackTerminal 判断状态是否属于回滚相关终态。
487	func isRollbackTerminal(status string) bool {
488		switch status {
489		case DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
490			return true
491		default:
492			return false
493		}
494	}
495	
496	// isRollbackFlowStatus 判断状态是否处于回滚流程（等待/进行中/任一回滚终态）。
497	func isRollbackFlowStatus(status string) bool {
498		switch status {
499		case DeviceAwaitingRollback, DeviceRollingBack,
500			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
501			return true
502		default:
503			return false
504		}
505	}
506	
507	// validateRollbackDisk 校验开启回滚的活动中单台设备的回滚状态自洽。
508	func validateRollbackDisk(campaignID string, dd diskDev) error {
509		bad := func(msg string) error {
510			return fmt.Errorf("%w: campaign %s device %s %s", ErrCorruptStorage, campaignID, dd.DeviceID, msg)
511		}
512		rb := dd.Rollback
513		// 回滚目标只能在首次领取下载时或之后锁定：有目标就必已领取下载。
514		// 反向不成立——领取下载时复查版本不兼容会直接失败，不锁定目标、也不回滚。
515		if dd.RollbackTarget != "" && !dd.Download.Claimed {
516			return bad("rollback target locked before download claim")
517		}
518		// 进入回滚流程的设备必然经过成功下载，目标一定已锁定。
519		if isRollbackFlowStatus(dd.Status) && dd.RollbackTarget == "" {
520			return bad("rollback status without locked target")
521		}
522		switch dd.Status {
523		case DeviceAwaitingRollback:
524			// 已接受安装失败、回滚尚未领取：回滚无结果。
525			if dd.Phase != StageRollback || rb.Claimed || rb.HasResult {
526				return bad("awaiting rollback state mismatch")
527			}
528			if !(dd.Install.HasResult && !dd.Install.Success) {
529				return bad("awaiting rollback without install failure")
530			}
531		case DeviceRollingBack:
532			if dd.Phase != StageRollback || !rb.Claimed || rb.HasResult {
533				return bad("rolling back state mismatch")
534			}
535		case DeviceRollbackSucceeded:
536			if dd.Phase != StageRollback || !rb.HasResult || !rb.Success {
537				return bad("rollback succeeded without success result")
538			}
539			if rb.ResultVersion != dd.RollbackTarget {
540				return bad("rollback version mismatch")
541			}
542			if _, ok := decodeObject(rb.ResultConfig); !ok {
543				return bad("rollback config invalid")
544			}
545		case DeviceRollbackFailed:
546			if dd.Phase != StageRollback || !rb.HasResult || rb.Success || rb.Reason == "" {
547				return bad("rollback failed without failure result")
548			}
549		case DeviceRollbackTimeout:
550			if dd.Phase != StageRollback {
551				return bad("rollback timeout phase mismatch")
552			}
553			// 等待回滚超时（未领取）或正在回滚超时（已领取未完成）都可能。
554			if rb.HasResult {
555				return bad("rollback timeout with result")
556			}
557		default:
558			// 其余状态：开启回滚后安装一旦失败必然进入回滚流程，
559			// 因此这里不能有安装失败，回滚操作也必须从未被领取或提交；
560			// 但回滚目标可能因已领取下载而存在（下载失败/超时/成功等）。
561			if dd.Install.HasResult && !dd.Install.Success {
562				return bad("install failure without rollback state")
563			}
564			if rb.Claimed || rb.HasResult {
565				return bad("rollback progressed without install failure")
566			}
567		}
568		return nil
569	}
570

