		if err != nil || dl == nil {
			t.Fatalf("claim download: %v %+v", err, dl)
		}
		if err := src.SubmitResult(OperationResult{
			CampaignID: spec2.ID, DeviceID: "d1", OperationID: dl.ID,
			At: base2.Add(time.Minute), Success: true,
		}); err != nil {
			t.Fatalf("download result: %v", err)
		}
