	t.Run("legacy id in v2 campaign", func(t *testing.T) {
		dir := setup(t)
		original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
			downloadDoc(doc)["id"] = "cmp-1:d1:download"
		})
		assertReopenCorrupt(t, dir, original)
