+// validV2OpID 校验标识是否是指定（活动, 设备, 阶段）的规范 v2 操作标识。
+func validV2OpID(opID, campaignID, deviceID, stage string) bool {
+	cid, did, st, ok := parseOperationIDV2(opID)
+	return ok && cid == campaignID && did == deviceID && st == stage
+}
